create schema if not exists maths;
alter table maths.user_notes alter column migration_run_id drop not null;
alter table maths.user_notes alter column source_row drop not null;
alter table maths.user_notes alter column source_row set default '{}'::jsonb;
create index if not exists maths_attempts_user_question_time_idx on maths.attempts(user_id, question_id, attempted_at desc);
create index if not exists maths_attempts_user_session_idx on maths.attempts(user_id, session_id, attempted_at);
create index if not exists maths_sessions_user_status_idx on maths.sessions(user_id, completed, updated_at desc);
create index if not exists maths_session_questions_session_position_idx on maths.session_questions(session_id, position);
create index if not exists maths_qbm_bank_question_idx on maths.question_bank_memberships(bank_key, question_id);
create index if not exists maths_psi_set_sequence_idx on maths.practice_set_items(set_id, sequence);
create or replace function maths._require_uid() returns uuid language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare v_uid uuid := auth.uid(); begin if v_uid is null then raise exception 'Authentication required' using errcode='28000'; end if; return v_uid; end $$;
create or replace function maths._norm(v text) returns text language sql immutable as $$ select lower(regexp_replace(btrim(coalesce(v,'')), '\s+', ' ', 'g')) $$;
create or replace function maths._chapter_group(v text) returns text language sql immutable as $$ select case when maths._norm(v) ~ '(fraction pattern|triplet|calculation memory|square|cube)' then 'misc' when maths._norm(v) ~ '(percentage|profit|loss|discount|ratio|proportion|average|mixture|alligation|interest|time.*work|pipe|cistern|speed|distance|train|boat|stream|partnership|ages|work.*wage)' then 'arithmetic' else 'advanced' end $$;
create or replace function maths._major_topic(ch text, tp text, st text, ct text) returns text language plpgsql immutable as $$ declare c text:=maths._norm(ch); t text:=maths._norm(tp); s text:=maths._norm(st); raw text:=maths._norm(coalesce(tp,'')||' '||coalesce(st,'')); begin if c='geometry' then if t='circle' or raw ~ '(chord|arc|tangent|secant|cyclic|semicircle|central angle|inscribed angle|common tangent)' then return 'Circle'; end if; if t ~ '(quadrilateral|polygon|parallelogram|rectangle|rhombus|square|trapez|kite)' or raw ~ '(quadrilateral|polygon|parallelogram|rectangle|rhombus|square|trapez|kite)' then return 'Quadrilateral & Polygon'; end if; if t ~ 'triangle' or raw ~ '(centroid|incenter|circumcenter|orthocenter|median|altitude|pythag|similar|congruen|equilateral|isosceles|midpoint theorem|apollonius)' then return 'Triangle'; end if; return 'Lines & Angles'; elsif c='mensuration 2d' then if raw ~ '(path|composite)' then return 'Paths / Composite 2D'; end if; if raw ~ '(circle|sector|semicircle|arc)' then return 'Circle'; end if; if raw ~ '(triangle|equilateral|isosceles|right[- ]?angled|right triangle)' then return 'Triangle'; end if; if raw ~ '(square|rectangle|parallelogram|rhombus|trapez|quadrilateral|kite)' then return 'Quadrilateral'; end if; if raw ~ '(polygon|hexagon)' then return 'Polygon'; end if; elsif c='mensuration 3d' then if raw ~ '(cuboid|cube|box)' then return 'Cuboid & Cube'; end if; if raw ~ 'cylinder' then return 'Cylinder'; end if; if raw ~ '(cone|frustum)' then return 'Cone & Frustum'; end if; if raw ~ '(sphere|hemisphere)' then return 'Sphere & Hemisphere'; end if; if raw ~ '(prism|pyramid|tetrahedron)' then return 'Prism & Pyramid'; end if; if raw ~ '(combination|composite|capsule|cavity|joined|recast|melting)' then return 'Composite Solids'; end if; elsif c='profit & loss and discount' then if raw ~ '(dishonest seller|false weight|false measure|short weight|cheat)' then return 'Dishonest Sellers'; end if; if t='discount' or raw ~ '(discount|marked price|markup)' then return 'Discount'; end if; return 'Profit & Loss'; end if; if s<>'' and s<>t and s not in ('general','basics','basic','overview','mixed','miscellaneous') and maths._norm(ct) in ('application','question','practice','problem') then return btrim(st); end if; return coalesce(nullif(btrim(tp),''),'General'); end $$;
create or replace function maths._setting(k text, fallback text) returns text language sql stable security definer set search_path=pg_catalog,public,maths as $$ select coalesce((select s.setting_value from maths.settings_snapshot s join maths.migration_runs r using(migration_run_id) where r.source_role='current_primary' and maths._norm(s.setting_key)=maths._norm(k) order by r.source_snapshot_at desc nulls last, s.source_row_number desc limit 1), fallback) $$;
create or replace function maths._study_day() returns integer language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare start_date date; today_ist date; d integer; begin begin start_date := maths._setting('plan_start_date', (current_timestamp at time zone 'Asia/Kolkata')::date::text)::date; exception when others then start_date := (current_timestamp at time zone 'Asia/Kolkata')::date; end; today_ist := (current_timestamp at time zone coalesce(nullif(maths._setting('study_timezone','Asia/Kolkata'),''),'Asia/Kolkata'))::date; d := today_ist-start_date+1; return greatest(1,coalesce(d,1)); end $$;
create or replace view maths.runtime_questions as select q.*, maths._chapter_group(q.chapter) as group_key, maths._major_topic(q.chapter,q.topic,q.subtopic,q.card_type) as major_topic, exists(select 1 from maths.question_bank_memberships b where b.question_id=q.question_id and upper(b.bank_key)='ACADEMIC') as bank_academic, exists(select 1 from maths.question_bank_memberships b where b.question_id=q.question_id and upper(b.bank_key) in ('CALCULATION','CALCULATION_TRAINING')) as bank_calculation, exists(select 1 from maths.question_bank_memberships b where b.question_id=q.question_id and upper(b.bank_key)='GENERATED') as bank_generated, exists(select 1 from maths.practice_set_items i where i.question_id=q.question_id and i.set_id='MOCK_QUESTIONS') as in_mock, exists(select 1 from maths.practice_set_items i where i.question_id=q.question_id and i.set_id='MOCK_FORMULA_REVISION') as in_formula_revision, exists(select 1 from maths.practice_set_items i where i.question_id=q.question_id and i.set_id='CALC_TRAINING') as in_calc_set, (lower(coalesce(q.status,'active')) not in ('inactive','archived','disabled')) as runtime_active, (lower(coalesce(q.status,'active')) not in ('inactive','archived','disabled') and exists(select 1 from maths.question_bank_memberships b where b.question_id=q.question_id and upper(b.bank_key)='ACADEMIC') and not exists(select 1 from maths.practice_set_items i where i.question_id=q.question_id and i.set_id in ('MOCK_QUESTIONS','MOCK_FORMULA_REVISION','CALC_TRAINING')) and not exists(select 1 from maths.question_bank_memberships b where b.question_id=q.question_id and upper(b.bank_key) in ('CALCULATION','CALCULATION_TRAINING','MOCK','MOCK_QUESTIONS','MOCK_FORMULA_REVISION')) and maths._norm(q.chapter) not in ('calculation training','calculation memory') and maths._norm(q.topic)<>'concepts' and maths._norm(q.card_type) not in ('formula','concept','memory','pattern','trap') and upper(coalesce(q.template_group,'')) not in ('MOCK_QUESTIONS','CALC_TRAINING') and upper(coalesce(q.template_group,'')) not like 'CALC_DAY%') as academic_eligible from maths.questions q;
create or replace function maths._user_runtime(p_uid uuid) returns table(question_id text, chapter text, topic text, subtopic text, major_topic text, group_key text, card_type text, prompt text, answer text, explanation text, memory_cue text, difficulty text, answer_mode text, option_a text, option_b text, option_c text, option_d text, correct_option text, template_group text, variant_types text, diagram_type text, diagram_json jsonb, source_file text, source_page text, added_at timestamptz, runtime_active boolean, academic_eligible boolean, bank_calculation boolean, bank_generated boolean, in_mock boolean, in_formula_revision boolean, in_calc_set boolean, state_attempts integer, mastered boolean, starred boolean, difficult boolean, last_state_result text, last_response_sec numeric, profile_total integer, profile_graded integer, profile_accuracy numeric, profile_avg_sec numeric, profile_last_result text, profile_last_at timestamptz, wrong_streak integer, correct_streak integer, expected_sec integer, weak boolean, hard boolean, review_interval integer, age_days integer, last_daily_day integer) language sql stable security definer set search_path=pg_catalog,public,maths as $$ with ranked as (select a.question_id,a.result,a.response_sec,a.attempted_at,row_number() over(partition by a.question_id order by a.attempted_at desc,a.attempt_id desc) rn,count(*) over(partition by a.question_id) total_count from maths.attempts a where a.user_id=p_uid), prof as (select question_id,max(total_count)::int total,count(*) filter(where rn<=5 and lower(result) in ('correct','wrong'))::int graded,count(*) filter(where rn<=5 and lower(result)='correct')::numeric / nullif(count(*) filter(where rn<=5 and lower(result) in ('correct','wrong')),0) accuracy,avg(response_sec) filter(where rn<=5 and coalesce(response_sec,0)>0) avg_sec,(array_agg(lower(coalesce(result,'')) order by rn) filter(where rn<=5))[1] last_result,(array_agg(attempted_at order by rn) filter(where rn<=5))[1] last_at,greatest(0,coalesce(min(rn) filter(where rn<=5 and lower(coalesce(result,''))<>'wrong'),6)-1)::int wrong_streak,greatest(0,coalesce(min(rn) filter(where rn<=5 and lower(coalesce(result,''))<>'correct'),6)-1)::int correct_streak from ranked where rn<=5 group by question_id), last_daily as (select sq.question_id,max(coalesce(nullif(s.params->>'planDay','')::int,0))::int last_day from maths.sessions s join maths.session_questions sq on sq.session_id=s.session_id where s.user_id=p_uid and lower(coalesce(s.mode,''))='daily' group by sq.question_id), base as (select rq.*,coalesce(st.attempts,0) state_attempts,coalesce(st.mastered,false) mastered,coalesce(st.marked,false) starred,coalesce(st.difficult,false) difficult,lower(coalesce(st.last_result,'')) last_state_result,coalesce(st.last_response_sec,0) last_response_sec,coalesce(p.total,0) profile_total,coalesce(p.graded,0) profile_graded,p.accuracy profile_accuracy,coalesce(p.avg_sec,0) profile_avg_sec,coalesce(p.last_result,'') profile_last_result,p.last_at profile_last_at,coalesce(p.wrong_streak,0) wrong_streak,coalesce(p.correct_streak,0) correct_streak,case when maths._norm(rq.chapter) in ('geometry','coordinate geometry') or length(coalesce(rq.prompt,''))>=220 then 45 else 30 end expected_sec,coalesce(ld.last_day,0) last_daily_day from maths.runtime_questions rq left join maths.question_state st on st.user_id=p_uid and st.question_id=rq.question_id left join prof p on p.question_id=rq.question_id left join last_daily ld on ld.question_id=rq.question_id), signals as (select b.*,(not b.mastered and b.profile_graded>=2 and (b.wrong_streak>=2 or (b.profile_graded>=3 and coalesce(b.profile_accuracy,1)<=.5) or (b.profile_total>=3 and b.profile_avg_sec>=b.expected_sec*1.5))) hard_calc,(not b.mastered and b.profile_total>0 and (b.profile_last_result='wrong' or (b.profile_graded>=2 and coalesce(b.profile_accuracy,1)<.75) or b.profile_avg_sec>=b.expected_sec)) weak_calc from base b) select question_id,chapter,topic,subtopic,major_topic,group_key,card_type,prompt,answer,explanation,memory_cue,difficulty,answer_mode,option_a,option_b,option_c,option_d,correct_option,template_group,variant_types,diagram_type,diagram_json,source_file,source_page,added_at,runtime_active,academic_eligible,bank_calculation,bank_generated,in_mock,in_formula_revision,in_calc_set,state_attempts,mastered,starred,difficult,last_state_result,last_response_sec,profile_total,profile_graded,profile_accuracy,profile_avg_sec,profile_last_result,profile_last_at,wrong_streak,correct_streak,expected_sec,weak_calc,hard_calc,case when profile_total=0 then 0 when profile_last_result='wrong' then 1 when hard_calc then 2 when weak_calc then 3 when starred then 7 when correct_streak>=3 then 14 when correct_streak>=2 then 7 else 3 end review_interval,case when profile_last_at is null then 999 else greatest(0,((current_timestamp at time zone 'Asia/Kolkata')::date-(profile_last_at at time zone 'Asia/Kolkata')::date)) end::int age_days,last_daily_day from signals $$;
create or replace function maths._metric(p_uid uuid, p_ids text[]) returns jsonb language sql stable security definer set search_path=pg_catalog,public,maths as $$ select jsonb_build_object('total',count(*),'attempted',count(*) filter(where r.state_attempts>0),'unseen',count(*) filter(where r.state_attempts=0),'coverage',case when count(*)=0 then 0 else round(100.0*count(*) filter(where r.state_attempts>0)/count(*),1) end,'wrong',count(*) filter(where r.profile_last_result='wrong'),'weak',count(*) filter(where r.weak),'hard',count(*) filter(where r.hard),'starred',count(*) filter(where r.starred),'difficult',count(*) filter(where r.difficult),'mastered',count(*) filter(where r.mastered)) from maths._user_runtime(p_uid) r where r.question_id=any(coalesce(p_ids,array[]::text[])) $$;
create or replace function maths._question_ids(p_uid uuid,p_scope text,p_chapter text default null,p_topic text default null,p_group text default null) returns text[] language sql stable security definer set search_path=pg_catalog,public,maths as $$ select coalesce(array_agg(r.question_id order by r.question_id),array[]::text[]) from maths._user_runtime(p_uid) r where case lower(coalesce(p_scope,'all')) when 'all' then r.academic_eligible when 'chapter' then r.academic_eligible and maths._norm(r.chapter)=maths._norm(p_chapter) when 'topic' then r.academic_eligible and maths._norm(r.chapter)=maths._norm(p_chapter) and (maths._norm(r.major_topic)=maths._norm(p_topic) or maths._norm(r.topic)=maths._norm(p_topic)) when 'group' then r.academic_eligible and r.group_key=lower(coalesce(p_group,'')) when 'new_practice' then r.academic_eligible and r.state_attempts=0 and (p_chapter is null or maths._norm(r.chapter)=maths._norm(p_chapter)) when 'starred' then r.academic_eligible and r.starred and not r.mastered when 'generated' then r.runtime_active and r.bank_generated else false end $$;
create or replace function maths._render_questions(p_uid uuid,p_ids text[],p_force_memory_reveal boolean default false) returns jsonb language sql stable security definer set search_path=pg_catalog,public,maths as $$ select coalesce(jsonb_agg(jsonb_build_object('questionId',r.question_id,'chapter',coalesce(r.chapter,''),'topic',coalesce(r.topic,''),'subtopic',coalesce(r.subtopic,''),'majorTopic',coalesce(r.major_topic,''),'prompt',r.prompt,'answer',coalesce(r.answer,''),'explanation',coalesce(r.explanation,''),'memoryCue',coalesce(r.memory_cue,''),'answerMode',case when p_force_memory_reveal or upper(coalesce(r.answer_mode,''))='REVEAL' or upper(coalesce(r.correct_option,'')) not in ('A','B','C','D') then 'REVEAL' else 'MCQ' end,'options',case when p_force_memory_reveal or upper(coalesce(r.answer_mode,''))='REVEAL' or upper(coalesce(r.correct_option,'')) not in ('A','B','C','D') then '[]'::jsonb else jsonb_build_array(jsonb_build_object('key','A','text',coalesce(r.option_a,'')),jsonb_build_object('key','B','text',coalesce(r.option_b,'')),jsonb_build_object('key','C','text',coalesce(r.option_c,'')),jsonb_build_object('key','D','text',coalesce(r.option_d,''))) end,'correctOption',case when p_force_memory_reveal or upper(coalesce(r.answer_mode,''))='REVEAL' then '' else upper(coalesce(r.correct_option,'')) end,'variantType',case when p_force_memory_reveal then 'CALC_RECALL' else coalesce(nullif(r.variant_types,''),nullif(r.template_group,''),'STATIC') end,'starred',r.starred,'difficult',r.difficult,'mastered',r.mastered,'inConcept',exists(select 1 from maths.concept_membership c where c.user_id=p_uid and c.question_id=r.question_id and c.active),'diagram',case when r.diagram_json is null then null else jsonb_build_object('type',r.diagram_type,'payload',r.diagram_json) end,'sourceFile',coalesce(r.source_file,''),'sourcePage',coalesce(r.source_page,'')) order by u.ord),'[]'::jsonb) from unnest(p_ids) with ordinality u(id,ord) join maths._user_runtime(p_uid) r on r.question_id=u.id $$;
create or replace function maths._get_session(p_uid uuid,p_session_id text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare s maths.sessions%rowtype; attempts_ jsonb; flags_ jsonb; total_ int; begin select * into s from maths.sessions where session_id=p_session_id and user_id=p_uid; if not found then raise exception 'Session not found'; end if; select count(*) into total_ from maths.session_questions where session_id=s.session_id; select coalesce(jsonb_object_agg(a.question_id,jsonb_build_object('result',lower(coalesce(a.result,'')),'selectedOption',coalesce(a.selected_option,''),'responseSec',coalesce(a.response_sec,0),'attemptId',a.attempt_id)),'{}'::jsonb) into attempts_ from (select distinct on(question_id) * from maths.attempts where user_id=p_uid and session_id=s.session_id order by question_id,attempted_at desc,attempt_id desc) a; select coalesce(jsonb_object_agg(r.question_id,jsonb_build_object('starred',r.starred,'difficult',r.difficult,'mastered',r.mastered,'inConcept',exists(select 1 from maths.concept_membership c where c.user_id=p_uid and c.question_id=r.question_id and c.active))),'{}'::jsonb) into flags_ from maths._user_runtime(p_uid) r where r.question_id in(select question_id from maths.session_questions where session_id=s.session_id); return jsonb_build_object('ok',true,'sessionId',s.session_id,'mode',coalesce(s.mode,''),'title',coalesce(s.title,''),'currentIndex',greatest(0,s.current_index),'completed',s.completed,'target',total_,'params',coalesce(s.params,'{}'::jsonb),'questions',coalesce(s.rendered_questions,'[]'::jsonb),'attempts',attempts_,'flags',flags_); end $$;
create or replace function maths._start_session(p_uid uuid,p_ids text[],p_mode text,p_title text,p_params jsonb default '{}'::jsonb,p_force_memory_reveal boolean default false) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare sid text:=gen_random_uuid()::text; rendered jsonb; i int:=0; qid text; begin if coalesce(array_length(p_ids,1),0)=0 then return jsonb_build_object('ok',false,'message','No eligible questions found.'); end if; rendered:=maths._render_questions(p_uid,p_ids,p_force_memory_reveal); insert into maths.sessions(session_id,user_id,mode,title,current_index,updated_at,completed,params,rendered_questions,created_at) values(sid,p_uid,p_mode,p_title,0,now(),false,coalesce(p_params,'{}'::jsonb),rendered,now()); foreach qid in array p_ids loop insert into maths.session_questions(session_id,question_id,position) values(sid,qid,i); i:=i+1; end loop; return maths._get_session(p_uid,sid); end $$;
create or replace function maths._select_by_kind(p_uid uuid,p_ids text[],p_kind text,p_count int default 20) returns text[] language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare k text:=lower(coalesce(p_kind,'random')); n int:=greatest(1,least(coalesce(p_count,20),100)); out_ids text[]; begin if k='all' then select coalesce(array_agg(r.question_id order by md5(r.question_id||current_date::text)),array[]::text[]) into out_ids from maths._user_runtime(p_uid) r where r.question_id=any(p_ids); elsif k='new' then select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and r.state_attempts=0 order by r.added_at desc nulls last,r.question_id limit n)x; elsif k='weak' then select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and r.weak order by r.hard desc,(r.profile_last_result='wrong') desc,coalesce(r.profile_accuracy,1),r.profile_avg_sec desc,r.question_id limit n)x; elsif k='hard' then select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and r.hard order by r.wrong_streak desc,coalesce(r.profile_accuracy,1),r.profile_avg_sec desc,r.question_id limit n)x; elsif k in ('starred','important') then select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and r.starred and not r.mastered order by random() limit n)x; elsif k='difficult' then select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and r.difficult and not r.mastered order by random() limit n)x; elsif k='due' then select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and (r.state_attempts=0 or r.profile_last_result='wrong' or r.difficult or (r.profile_total>0 and r.age_days>=r.review_interval)) and not r.mastered order by (r.profile_last_result='wrong') desc,r.difficult desc,r.weak desc,r.age_days desc limit n)x; else select coalesce(array_agg(x.question_id),array[]::text[]) into out_ids from(select r.question_id from maths._user_runtime(p_uid) r where r.question_id=any(p_ids) and not r.mastered order by random() limit n)x; end if; return out_ids; end $$;
create or replace function maths._select_daily_ids(p_uid uuid,p_day int,p_size int,p_exclude text[] default array[]::text[]) returns text[] language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare picked text[]:=array[]::text[]; chapter_counts jsonb:='{}'::jsonb; q record; quota int:=greatest(0,least(p_size,coalesce(nullif(maths._setting('daily_new_quota','7'), '')::int,7))); rotation int:=greatest(1,coalesce(nullif(maths._setting('difficult_rotation_days','3'),'')::int,3)); fresh_days int:=greatest(1,coalesce(nullif(maths._setting('new_content_window_days','60'),'')::int,60)); stage int; key_ text; cnt int; begin for stage in 1..6 loop loop exit when coalesce(array_length(picked,1),0)>=p_size; exit when stage<=2 and coalesce(array_length(picked,1),0)>=quota; select r.* into q from maths._user_runtime(p_uid) r where r.academic_eligible and not r.mastered and not (r.question_id=any(coalesce(picked,array[]::text[]))) and not(r.question_id=any(coalesce(p_exclude,array[]::text[]))) and (not r.difficult or r.last_daily_day=0 or p_day-r.last_daily_day>=rotation) and case stage when 1 then r.state_attempts=0 and r.added_at is not null and r.added_at >= now()-(fresh_days||' days')::interval when 2 then r.state_attempts=0 when 3 then r.difficult and (r.last_daily_day=0 or p_day-r.last_daily_day>=rotation) when 4 then r.weak and r.age_days>=r.review_interval when 5 then r.profile_total>0 and r.age_days>=r.review_interval else true end order by coalesce((chapter_counts->>maths._norm(r.chapter))::int,0), case when r.profile_last_result='wrong' then 90000 when r.hard then 75000 when r.weak then 55000 else 0 end +case when r.starred then 12000 else 0 end +least(45000,r.age_days*3500)+least(25000,greatest(0,p_day-r.last_daily_day)*4000) +(abs(hashtext(r.question_id||':'||p_day::text))%5000) desc, r.added_at desc nulls last,r.question_id limit 1; exit when not found; picked:=array_append(picked,q.question_id); key_:=maths._norm(q.chapter); cnt:=coalesce((chapter_counts->>key_)::int,0)+1; chapter_counts:=jsonb_set(chapter_counts,array[key_],to_jsonb(cnt),true); end loop; end loop; return picked; end $$;


